    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> count;
    int l = 0, best = 0;
    for (int rr = 0; rr < n; rr++) {
        count[a[rr]]++;
        while (count[a[rr]] > k) {
            count[a[l]]--;
            l++;
        }
        best = max(best, rr - l + 1);
    }
    cout << best << "\n";

    return 0;
}

